using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: captures OpenTelemetry traces from AI chat interactions
/// to verify instrumentation and inspect call patterns.
/// </summary>
[TestClass]
public class TelemetryEvals
{
    private static readonly List<System.Diagnostics.Activity> ExportedActivities = [];

    private static TracerProvider? _tracerProvider;

    [ClassInitialize]
    public static void SetupTelemetry(TestContext _)
    {
        _tracerProvider = Sdk.CreateTracerProviderBuilder()
            .SetResourceBuilder(ResourceBuilder.CreateDefault().AddService("MyApp.Evals"))
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("Azure.*")
            .AddInMemoryExporter(ExportedActivities)
            .AddOtlpExporter()
            .Build();
    }

    [ClassCleanup]
    public static void TeardownTelemetry()
    {
        _tracerProvider?.Dispose();
    }

    [TestMethod]
    public async Task ChatCompletion_EmitsTraceSpans()
    {
        IChatClient client = CreateInstrumentedClient();

        var response = await client.GetResponseAsync("What is 2 + 2?");

        _tracerProvider?.ForceFlush();

        Assert.IsTrue(
            ExportedActivities.Count > 0,
            "Expected at least one telemetry span from the chat completion call.");
    }

    [TestMethod]
    public async Task ChatCompletion_SpanContainsModelAttribute()
    {
        IChatClient client = CreateInstrumentedClient();

        await client.GetResponseAsync("Hello");

        _tracerProvider?.ForceFlush();

        var span = ExportedActivities.FirstOrDefault(a =>
            a.Tags.Any(t => t.Key == "gen_ai.request.model"));

        Assert.IsNotNull(span, "Expected a span with gen_ai.request.model attribute.");
    }

    private static IChatClient CreateInstrumentedClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost:8080";
        var model = Environment.GetEnvironmentVariable("AZURE_OPENAI_MODEL")
            ?? "gpt-4o-mini";

        return new ChatClientBuilder(new Azure.AI.Inference.ChatCompletionsClient(
                new Uri(endpoint),
                new Azure.AzureKeyCredential(
                    Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY") ?? "test-key")))
            .UseOpenTelemetry()
            .Build(new Azure.AI.Inference.ChatCompletionsClient(
                new Uri(endpoint),
                new Azure.AzureKeyCredential(
                    Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY") ?? "test-key")));
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Quality mode: evaluates AI response quality using built-in metrics
/// (relevance, coherence, fluency, groundedness).
/// </summary>
[TestClass]
public class QualityEvals
{
    private static ReportingConfiguration? _reportingConfig;

    [ClassInitialize]
    public static void Setup(TestContext _)
    {
        var storageDir = Path.Combine(
            Path.GetTempPath(), "MyApp.Evals", "quality-results");

        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        _reportingConfig = DiskBasedReportingConfiguration.Create(
            storageRootDir: storageDir,
            evaluators: evaluators,
            chatConfiguration: GetJudgeChatConfiguration());
    }

    [TestMethod]
    public async Task CoachResponse_MeetsQualityThresholds()
    {
        await using var scenario = await _reportingConfig!.CreateScenarioRunAsync(
            scenarioName: nameof(CoachResponse_MeetsQualityThresholds));

        IChatClient client = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coaching assistant."),
            new(ChatRole.User, "How can I improve my time management skills?"),
        };

        var response = await client.GetResponseAsync(messages);
        var modelResponse = response.Text ?? string.Empty;

        // Evaluate quality
        await scenario.EvaluateAsync(
            messages,
            new ChatMessage(ChatRole.Assistant, modelResponse));

        // Assert each metric meets minimum threshold
        foreach (var result in scenario.GetEvaluationResults())
        {
            if (result is NumericMetricResult numeric)
            {
                Assert.IsTrue(
                    numeric.Value >= 3.0,
                    $"Metric '{numeric.Name}' scored {numeric.Value}, expected >= 3.0");
            }
        }
    }

    [TestMethod]
    public async Task CoachResponse_GroundedInContext()
    {
        await using var scenario = await _reportingConfig!.CreateScenarioRunAsync(
            scenarioName: nameof(CoachResponse_GroundedInContext));

        IChatClient client = scenario.ChatConfiguration!.ChatClient;

        var context = "The user has 3 meetings today: standup at 9am, design review at 11am, and 1:1 at 3pm.";

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, $"You are a scheduling assistant. Context: {context}"),
            new(ChatRole.User, "What meetings do I have today?"),
        };

        var response = await client.GetResponseAsync(messages);

        await scenario.EvaluateAsync(
            messages,
            new ChatMessage(ChatRole.Assistant, response.Text ?? string.Empty),
            additionalContext: [new EvaluationContext("grounding", context)]);
    }

    private static ChatConfiguration GetJudgeChatConfiguration()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost:8080";
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
            ?? "test-key";

        IChatClient judgeChatClient = new Azure.AI.Inference.ChatCompletionsClient(
                new Uri(endpoint),
                new Azure.AzureKeyCredential(key))
            .AsChatClient("gpt-4o-mini");

        return new ChatConfiguration(judgeChatClient);
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Compare mode: runs the same prompts against multiple model configurations
/// and produces a side-by-side report for regression detection.
/// </summary>
[TestClass]
public class CompareEvals
{
    private static readonly string StorageDir = Path.Combine(
        Path.GetTempPath(), "MyApp.Evals", "compare-results");

    private static readonly string[] TestPrompts =
    [
        "Explain the importance of code reviews in two sentences.",
        "What are three benefits of pair programming?",
        "How should I handle a disagreement with a coworker?",
    ];

    [TestMethod]
    public async Task CompareModelConfigurations()
    {
        var configurations = GetCompareConfigurations();

        foreach (var (label, chatConfig) in configurations)
        {
            var evaluators = new IEvaluator[]
            {
                new RelevanceEvaluator(),
                new CoherenceEvaluator(),
                new FluencyEvaluator(),
            };

            var reportingConfig = DiskBasedReportingConfiguration.Create(
                storageRootDir: Path.Combine(StorageDir, label),
                evaluators: evaluators,
                chatConfiguration: chatConfig);

            foreach (var prompt in TestPrompts)
            {
                var scenarioName = $"Compare_{label}_{prompt[..Math.Min(30, prompt.Length)]}";

                await using var scenario = await reportingConfig.CreateScenarioRunAsync(
                    scenarioName: scenarioName);

                IChatClient client = scenario.ChatConfiguration!.ChatClient;

                var messages = new List<ChatMessage>
                {
                    new(ChatRole.System, "You are a helpful coaching assistant. Be concise."),
                    new(ChatRole.User, prompt),
                };

                var response = await client.GetResponseAsync(messages);

                await scenario.EvaluateAsync(
                    messages,
                    new ChatMessage(ChatRole.Assistant, response.Text ?? string.Empty));
            }
        }
    }

    [TestMethod]
    public async Task CompareTemperatureSettings()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost:8080";
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
            ?? "test-key";

        float[] temperatures = [0.0f, 0.5f, 1.0f];

        foreach (var temp in temperatures)
        {
            var label = $"temp_{temp:F1}";

            IChatClient client = new Azure.AI.Inference.ChatCompletionsClient(
                    new Uri(endpoint),
                    new Azure.AzureKeyCredential(key))
                .AsChatClient("gpt-4o-mini");

            var evaluators = new IEvaluator[] { new CoherenceEvaluator() };

            var chatConfig = new ChatConfiguration(client);
            var reportingConfig = DiskBasedReportingConfiguration.Create(
                storageRootDir: Path.Combine(StorageDir, label),
                evaluators: evaluators,
                chatConfiguration: chatConfig);

            await using var scenario = await reportingConfig.CreateScenarioRunAsync(
                scenarioName: $"Temperature_{label}");

            var messages = new List<ChatMessage>
            {
                new(ChatRole.User, "Give me a motivational quote about teamwork."),
            };

            var options = new ChatOptions { Temperature = temp };
            var response = await client.GetResponseAsync(messages, options);

            await scenario.EvaluateAsync(
                messages,
                new ChatMessage(ChatRole.Assistant, response.Text ?? string.Empty));
        }
    }

    private static List<(string Label, ChatConfiguration Config)> GetCompareConfigurations()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost:8080";
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
            ?? "test-key";

        var models = new[] { "gpt-4o-mini", "gpt-4o" };
        var configs = new List<(string, ChatConfiguration)>();

        foreach (var model in models)
        {
            IChatClient client = new Azure.AI.Inference.ChatCompletionsClient(
                    new Uri(endpoint),
                    new Azure.AzureKeyCredential(key))
                .AsChatClient(model);

            configs.Add((model, new ChatConfiguration(client)));
        }

        return configs;
    }
}

