using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using Azure.AI.OpenAI;
using System.ClientModel;

namespace MyApp.Evals;

/// <summary>
/// Quality mode: evaluates AI response quality using built-in metrics
/// (relevance, coherence, fluency, groundedness).
/// </summary>
[TestClass]
public class QualityEvals
{
    private static ReportingConfiguration? _reportingConfig;

    [ClassInitialize]
    public static void Setup(TestContext _)
    {
        var storageDir = Path.Combine(
            Path.GetTempPath(), "MyApp.Evals", "quality-results");

        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        _reportingConfig = DiskBasedReportingConfiguration.Create(
            storageRootDir: storageDir,
            evaluators: evaluators,
            chatConfiguration: GetJudgeChatConfiguration());
    }

    [TestMethod]
    public async Task CoachResponse_MeetsQualityThresholds()
    {
        await using var scenario = await _reportingConfig!.CreateScenarioRunAsync(
            scenarioName: nameof(CoachResponse_MeetsQualityThresholds));

        IChatClient client = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coaching assistant."),
            new(ChatRole.User, "How can I improve my time management skills?"),
        };

        var response = await client.GetResponseAsync(messages);
        var modelResponse = response.Text ?? string.Empty;

        await scenario.EvaluateAsync(
            messages,
            new ChatMessage(ChatRole.Assistant, modelResponse));

        foreach (var result in scenario.GetEvaluationResults())
        {
            if (result is NumericMetricResult numeric)
            {
                Assert.IsTrue(
                    numeric.Value >= 3.0,
                    $"Metric '{numeric.Name}' scored {numeric.Value}, expected >= 3.0");
            }
        }
    }

    [TestMethod]
    public async Task CoachResponse_GroundedInContext()
    {
        await using var scenario = await _reportingConfig!.CreateScenarioRunAsync(
            scenarioName: nameof(CoachResponse_GroundedInContext));

        IChatClient client = scenario.ChatConfiguration!.ChatClient;

        var context = "The user has 3 meetings today: standup at 9am, design review at 11am, and 1:1 at 3pm.";

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, $"You are a scheduling assistant. Context: {context}"),
            new(ChatRole.User, "What meetings do I have today?"),
        };

        var response = await client.GetResponseAsync(messages);

        await scenario.EvaluateAsync(
            messages,
            new ChatMessage(ChatRole.Assistant, response.Text ?? string.Empty),
            additionalContext: [new EvaluationContext("grounding", context)]);
    }

    private static ChatConfiguration GetJudgeChatConfiguration()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost:8080";
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
            ?? "test-key";

        var openAiClient = new AzureOpenAIClient(
            new Uri(endpoint),
            new ApiKeyCredential(key));

        IChatClient judgeChatClient = openAiClient
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();

        return new ChatConfiguration(judgeChatClient);
    }
}

