using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;
using Azure.AI.OpenAI;
using System.ClientModel;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: captures OpenTelemetry traces from AI chat interactions
/// to verify instrumentation and inspect call patterns.
/// </summary>
[TestClass]
public class TelemetryEvals
{
    private static readonly List<System.Diagnostics.Activity> ExportedActivities = [];

    private static TracerProvider? _tracerProvider;

    [ClassInitialize]
    public static void SetupTelemetry(TestContext _)
    {
        _tracerProvider = Sdk.CreateTracerProviderBuilder()
            .SetResourceBuilder(ResourceBuilder.CreateDefault().AddService("MyApp.Evals"))
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("Azure.*")
            .AddInMemoryExporter(ExportedActivities)
            .AddOtlpExporter()
            .Build();
    }

    [ClassCleanup]
    public static void TeardownTelemetry()
    {
        _tracerProvider?.Dispose();
    }

    [TestMethod]
    public async Task ChatCompletion_EmitsTraceSpans()
    {
        IChatClient client = CreateInstrumentedClient();

        await client.GetResponseAsync("What is 2 + 2?");

        _tracerProvider?.ForceFlush();

        Assert.IsTrue(
            ExportedActivities.Count > 0,
            "Expected at least one telemetry span from the chat completion call.");
    }

    [TestMethod]
    public async Task ChatCompletion_SpanContainsModelAttribute()
    {
        IChatClient client = CreateInstrumentedClient();

        await client.GetResponseAsync("Hello");

        _tracerProvider?.ForceFlush();

        var span = ExportedActivities.FirstOrDefault(a =>
            a.Tags.Any(t => t.Key == "gen_ai.request.model"));

        Assert.IsNotNull(span, "Expected a span with gen_ai.request.model attribute.");
    }

    private static IChatClient CreateInstrumentedClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost:8080";
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
            ?? "test-key";
        var model = Environment.GetEnvironmentVariable("AZURE_OPENAI_MODEL")
            ?? "gpt-4o-mini";

        var openAiClient = new AzureOpenAIClient(
            new Uri(endpoint),
            new ApiKeyCredential(key));

        return openAiClient
            .GetChatClient(model)
            .AsIChatClient()
            .AsBuilder()
            .UseOpenTelemetry()
            .Build();
    }
}

