using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using Azure.AI.OpenAI;
using System.ClientModel;

namespace MyApp.Evals;

/// <summary>
/// Compare mode: runs the same prompts against multiple model configurations
/// and produces a side-by-side report for regression detection.
/// </summary>
[TestClass]
public class CompareEvals
{
    private static readonly string StorageDir = Path.Combine(
        Path.GetTempPath(), "MyApp.Evals", "compare-results");

    private static readonly string[] TestPrompts =
    [
        "Explain the importance of code reviews in two sentences.",
        "What are three benefits of pair programming?",
        "How should I handle a disagreement with a coworker?",
    ];

    [TestMethod]
    public async Task CompareModelConfigurations()
    {
        var configurations = GetCompareConfigurations();

        foreach (var (label, chatConfig) in configurations)
        {
            var evaluators = new IEvaluator[]
            {
                new RelevanceEvaluator(),
                new CoherenceEvaluator(),
                new FluencyEvaluator(),
            };

            var reportingConfig = DiskBasedReportingConfiguration.Create(
                Path.Combine(StorageDir, label), evaluators, chatConfig);

            foreach (var prompt in TestPrompts)
            {
                var scenarioName = $"Compare_{label}_{prompt[..Math.Min(30, prompt.Length)]}";

                await using var scenario = await reportingConfig.CreateScenarioRunAsync(scenarioName);

                IChatClient client = scenario.ChatConfiguration!.ChatClient;

                var messages = new List<ChatMessage>
                {
                    new(ChatRole.System, "You are a helpful coaching assistant. Be concise."),
                    new(ChatRole.User, prompt),
                };

                ChatResponse response = await client.GetResponseAsync(messages);

                await scenario.EvaluateAsync(messages, response);
            }
        }
    }

    [TestMethod]
    public async Task CompareTemperatureSettings()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost:8080";
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
            ?? "test-key";

        float[] temperatures = [0.0f, 0.5f, 1.0f];

        foreach (var temp in temperatures)
        {
            var label = $"temp_{temp:F1}";

            var openAiClient = new AzureOpenAIClient(
                new Uri(endpoint),
                new ApiKeyCredential(key));

            IChatClient client = openAiClient
                .GetChatClient("gpt-4o-mini")
                .AsIChatClient();

            var evaluators = new IEvaluator[] { new CoherenceEvaluator() };

            var chatConfig = new ChatConfiguration(client);
            var reportingConfig = DiskBasedReportingConfiguration.Create(
                Path.Combine(StorageDir, label), evaluators, chatConfig);

            await using var scenario = await reportingConfig.CreateScenarioRunAsync(
                $"Temperature_{label}");

            var messages = new List<ChatMessage>
            {
                new(ChatRole.User, "Give me a motivational quote about teamwork."),
            };

            var options = new ChatOptions { Temperature = temp };
            ChatResponse response = await client.GetResponseAsync(messages, options);

            await scenario.EvaluateAsync(messages, response);
        }
    }

    private static List<(string Label, ChatConfiguration Config)> GetCompareConfigurations()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost:8080";
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY")
            ?? "test-key";

        var models = new[] { "gpt-4o-mini", "gpt-4o" };
        var configs = new List<(string, ChatConfiguration)>();

        foreach (var model in models)
        {
            var openAiClient = new AzureOpenAIClient(
                new Uri(endpoint),
                new ApiKeyCredential(key));

            IChatClient client = openAiClient
                .GetChatClient(model)
                .AsIChatClient();

            configs.Add((model, new ChatConfiguration(client)));
        }

        return configs;
    }
}

